css:
/* ONE decision, and the rest is arithmetic. GROW is the knob.
   ROOM is the space the swell physically takes on every side —
   half the extra width, exactly — so the neighbours are never
   merely NEAR clear of it. AURA is the part that is not
   arithmetic: the push beyond what the geometry demands, which
   is the difference between a cluster making room and a
   cluster being repelled. */
const grow = 1.16 + 0.22 * pull;
const room = CHIP * (grow - 1) / 2;
const aura = 3 + 9 * pull;

/* And the shove is a VECTOR, which is the whole reason these
   are a cluster and not a row. In a line the direction reduces
   to a sign and every chip is pushed along the same axis
   whatever its actual relationship to the one you pressed;
   here each one goes the way it lies. The aura decays with
   real distance — exp() rather than 1/d, because an inverse
   law is violent at the first neighbour and flat everywhere
   after. */
const dx = p.x - sel.x, dy = p.y - sel.y;
const gap = Math.hypot(dx, dy), far = gap / PITCH;
const fall = Math.exp(-(far - 1) / 1.8);
const push = room + aura * fall;

/* The selected chip goes WIDE BEFORE IT GOES TALL: two springs
   at different stiffnesses rather than one scale, so the
   transient is anisotropic and the rest state is not. That is
   the whole of the jelly, and it is four numbers rather than a
   keyframe track — which matters, because a keyframed squash
   is the same squash at every bounce setting and this one is
   not there at all when the spring is critically damped. The
   far chips are 22ms late per step, which is what makes it a
   force travelling outward rather than a layout changing all
   at once. */
animate={{ x: (dx / gap) * push, y: (dy / gap) * push,
           scaleX: s, scaleY: s, rotate: (dx / gap) * tilt * fall }}
transition={{
  x:      { ...swing(k),        delay: far * 0.022 },
  scaleX: { ...swing(k * 1.24), delay: far * 0.022 },
  scaleY: { ...swing(k * 0.86), delay: far * 0.022 },
}}

/* The hover is NOT any of this. It lives on an inner element
   with a CSS transform, because CSS scale and transform are
   applied in sequence rather than folded together and a rule
   here would fight the spring above every frame. Two elements,
   two transforms — and it buys the hover its own curve, which
   it needs: the field springs, a hover must not. Same 1.045
   and the same 260ms as the search block, small enough to be
   felt rather than seen. */

/* The handle follows the finger exactly and the offset is
   taken at the FIRST MOVE, never at the press. Deciding it on
   pointerdown is what makes a slider teleport: a press away
   from the handle sets the offset to the handle's own middle
   and the first move jumps it the whole way in one frame. */
const move = (e) => {
  const at = local(e.clientX);
  if (grab === null) { grab = at - x.get(); return; }
  x.set(clamp(at - grab, 0, TRAVEL));
};

/* And the commit is a MORPH, not a hand-over. The handle's
   width and its offset move together and by the same amount,
   so the right edge is stationary and the handle opens out
   behind itself to fill the track it crossed. A scale would
   have dragged the corner radius with it. */
animate(x, TRAVEL, spring);
setDone(true);          /* width: GRIP -> span - PAD * 2 */

/* The pill grows because one number changes: the width
   of the rail the faces sit in. They are absolutely placed
   inside it, so nobody moves when somebody arrives — there is
   simply more room, and CSS carries the width across.

   Worked out rather than measured. Every block on this bench
   is drawn at a fraction of its own size, and a layout
   animation that measures screen rectangles gets a different
   answer at every zoom. Arithmetic gets the same one. */
const rail = picked.length
  ? FACE + (picked.length - 1) * (FACE - overlap)
  : 0;

.pik-rail {
  position: relative;
  transition: width 300ms cubic-bezier(0.33, 0.55, 0.2, 1);
}
.pik-face {
  position: absolute;
  transform: translateX(/* i * (FACE - overlap) */);
  /* the gap between two faces is the CARD's colour, not white,
     or the stack grows a halo in dark mode */
  box-shadow: 0 0 0 2px var(--fill-slab, var(--card));
}

/* ── Grid ─────────────────────────────────────────────────
   The same four faces packed into the footprint of ONE, so
   the pill does not grow at all. Nothing overlaps, which is
   the point: a row hides parts of faces behind other faces,
   the quad shows all of every face and pays in size.

   The box does not fill up — it SUBDIVIDES. One face is the
   whole box, four are a quarter each, and three fill reading
   order and leave the last cell empty: the quad is four fixed
   slots, so three people occupy three of them.

   Placed by transform, not by left/top/width/height, so a
   face changing arrangement travels instead of teleporting —
   one vector and one scale describe both layouts. */
const cell = (FACE - gutter) / 2;
const scale = cell / FACE;

/* NOTHING EVER LEAVES THE FRAME, and that is the whole
   arrangement. This was a row twice — cards in a line, the
   ones at the ends either dissolving into a mask or cut by
   the edge of a box — and both are answers to the same
   question: what happens to a card when it runs out of block?
   A ring does not ask it. The furthest a card gets is the
   radius, which is a number the component chose. */
const th = (i - turn) * (Math.PI * 2 / n);
const f  = (Math.cos(th) + 1) / 2;   /* 1 front, 0 back */
const x  = Math.sin(th) * orbit;
const s  = mix(backScale, 1, f);

/* IT IS THEREFORE ENDLESS. A row has a first card and a last
   one and has to decide what to do at each; a ring has
   neither, so the swipe never runs out and never rubber-bands.
   Swipe once and the front card shrinks and goes to the back
   while the next comes forward — which falls out of the
   geometry rather than being animated on top of it. */

/* AND THE ANGLE IS NOT TAKEN MODULO ANYTHING. Wrapping turn
   to 0..360 sends a card the long way round the moment it
   crosses the seam, which is the one visible bug this
   arrangement can have. */
turn.current = turn0 - dx / PULL;   /* no clamp, no wrap */

/* THE BACK OF THE RING RIDES UP. Scale alone says smaller,
   which reads as further away OR as literally smaller; a card
   that also lifts as it recedes is unmistakably going back,
   because that is what a ring seen from slightly above does.
   One term, and most of what makes the depth read. */
const y = -(1 - f) * 22;

/* PAINT ORDER IS A Z-INDEX, BY HAND. Everything here is 2D —
   scale and offset, not translateZ — so nothing sorts itself
   and a card would paint in DOM order over the one in front
   of it. f already knows which is nearer. */
const z = Math.round(f * 100);

/* THREE MOTIONS, THREE ELEMENTS, ONE TRANSFORM EACH. The slot
   carries the ring, the floater the drift, the card the tilt.
   One node cannot be written by three authors — a drag, a CSS
   animation and a pair of springs — without one losing. */
<div className="slot">      /* placed by the drag  */
  <div className="float">   /* keyframes, untouched */
    <div className="card" />/* sprung by the pointer */

/* IT SINKS, IT DOES NOT LIFT. Every tilt card rotates TOWARD
   the cursor; this one goes away under it. One minus sign,
   and it is the difference between a surface being displayed
   to you and one being touched. */
const rx = -ny * max;
const ry =  nx * max;

e=>`/* ONE body, deformed by its own speed. A trail would put a
   second circle behind this one, and that reads as exactly
   what it is — a thread while you drag slowly and a detached
   blob when you drag fast. Stretch lengthens the single body
   into its direction of travel instead, so the elasticity has
   nothing to leave behind. */
<Liquid blur={4.5} contrast={16} fill="var(--board)" filterPadding={80}>
  <Liquid.Item
    effect="move"
    move={{ springiness: ${xy(Number(e.give)/100,2)}, stretch: ${xy(Number(e.stretch)/100,2)}, wobble: 0.35, trail: 0 }}
  >
    <motion.span
      drag
      dragConstraints={{ left: -122, right: 122, top: -72, bottom: 72 }}
      dragElastic={0.14}
      dragMomentum={false}
      style={{ width: ${e.size}, height: ${e.size} }}
    />
  </Liquid.Item>
</Liquid>

/* the ball carries no fill of its own — the group paints the
   merged silhouette behind it, and a background here would lay
   a hard circle over the liquid edge */
.drg-ball { border-radius: 999px; cursor: grab; touch-action: none; }

/* AND IT HAS TO BE GRABBED, not just dragged. Three beats,
   and none of them is the drag: hover swells it a little so
   you know it is live, the press PINCHES it, and letting go
   rounds it back out on a spring. */
whileHover={{ scaleX: 1.03, scaleY: 1.03 }}
whileTap={{ scaleX: 0.92, scaleY: 1.04 }}
transition={{ type: "spring", stiffness: 520, damping: 24 }}

/* A PINCH, NOT A SHRINK. A circle that gets uniformly smaller
   reads as a button being pressed INTO a surface; this one is
   not on a surface, it is in your hand, and what a held ball
   does is narrow across the grip and bulge along it. Area is
   roughly kept, so it reads as squeezed rather than resized.

   It works because the metaball library renders its children
   inside the filtered group rather than drawing circles from
   their measurements — so a CSS transform on the span comes
   through in the painted silhouette. */

/* ONE NOTE IN, ONE NOTE OUT, whichever event brings it. The
   sounds hung off onDragStart/onDragEnd, so a press that
   never moved was silent — which is exactly the gesture the
   squeeze was added for. Both handlers are idempotent and
   wired to the pointer AND the drag, so whichever framer
   forwards first makes the sound and the other does nothing;
   the pair can never go out of balance. */
const grab = () => { if (armed.current) return;
                     armed.current = true;  play("lift"); };
const drop = () => { if (!armed.current) return;
                     armed.current = false; play("drop"); };`

/* THE PART THAT MATTERS: the commitment happens at a
   DISTANCE, not on release. Crossing the threshold is what
   arms the refresh, so you know it will happen while your
   finger is still down — let go after that and it goes, and
   you knew. A version that decides on release has hidden the
   only information the gesture carries. */

/* Rubber, not a rail. A linear pull reaches the threshold at
   exactly the threshold and tells you nothing on the way;
   this saturates, so the last twenty pixels cost more than
   the first twenty and RESISTANCE is what you feel rather
   than distance. */
const R     = 700 - (resistance / 100) * 380;
const drawn = (R * raw) / (R + raw);
const p     = clamp(at / threshold, 0, 1);

/* THE GOO IS THE COMMITMENT, not a decoration on it. Five
   droplets sit scattered at rest and are drawn together as
   you pull; crossing the threshold is the moment they touch
   and fuse into one body. That fusion is legible at a glance
   and at a distance, which is exactly what this gesture has
   to communicate before you let go. One number does it: */
--spread: 20 - p * 17.5;     /* px from the centre, each drop */
transform: rotate(calc(var(--a) + var(--turn)))
           translateY(calc(var(--spread) * -1px));

/* The ring turns as a WHOLE while it works — the animation is
   on the group box, not on the droplets — so the DOM and the
   liquid silhouette rotate together and the library never
   re-measures a moving rect. */
.bal[data-phase="work"] .bal-goo { animation: bal-spin var(--rpm) linear infinite; }

/* ONE ARRAY IS THE WHOLE TRUTH. The balance is the last
   point, the change is last minus first, the percentage is
   that over the first, and the scrub just moves the index.
   They were three hand-written figures beside a decorative
   line — three things that can disagree with each other and
   with the chart above them. */
const value  = series[scrub ?? series.length - 1];
const change = value - series[0];

/* The scrub reads a FRACTION of the plot's own box, so it
   needs no zoom correction: both sides of the division are
   screen pixels and the ratio holds at any scale. It snaps to
   a real reading rather than interpolating between two and
   presenting the result as a measurement. */
const t = clamp((e.clientX - r.left) / r.width, 0, 1);
setScrub(Math.round(t * last));

/* NO MONO. tabular-nums is the only thing the monospaced face
   was providing — same advance for every digit, so nothing
   shifts as the number changes under the pointer — and Inter
   has it. */
font-variant-numeric: tabular-nums;

/* Tracking the finger is instant, because it IS the finger.
   The spring is only ever the journey home — elasticity is
   feedback, never latency. */
useSpring(target, 58, /* instant while */ dragging);

/* A slider whose value has mass.

   The handle is RIGID. It is under your finger, and anything
   under a finger that lags it is broken. The fill is a second
   spring behind it — softer, barely damped — so a fast drag
   throws it past the handle, into the end stop, and rocks it
   back two or three times before it settles. */

/* Stiffness falls and damping rises together, which is why
   these are one knob and not two: thin liquid is slow to
   answer and slow to forget, and that is the same sentence
   twice. 0 is exactly an ordinary slider and has to be
   exactly that, not a very stiff spring that still rings. */
const soft  = viscosity / 100;
const stiff = 0.34 - soft * 0.29;
const damp  = 0.74 + soft * 0.22;

fv += (value - fill) * stiff * dt;
fv *= Math.pow(damp, dt);      /* per FRAME, so a dropped one
                                  cannot double the loss */
fill += fv * dt;

/* The end stop is a wall, and a wall gives some back. Without
   this the overshoot at the top of the track is swallowed and
   the liquid stops behaving like liquid exactly where you are
   looking at it. */
if (fill > 100) { fill = 100; fv = -fv * 0.42; }
if (fill < 0)   { fill = 0;   fv = -fv * 0.42; }

/* The release is a throw, not a stop: the handle leaves along
   the velocity it actually had and decelerates. */
value += hv * dt;
hv    *= Math.pow(0.86 + (momentum / 100) * 0.115, dt);

/* THE MENISCUS is what sells it. A bar that lags is a laggy
   bar; a bar whose leading edge leans the way it is going is
   a surface with momentum in it. Clipped, never skewed — a
   skew leans the whole body and lifts the bottom edge off the
   floor of the track, which is a bar tipping over. */
--lean: clamp(-20px, (tilt / 100) * fv * 3, 20px);
clip-path: polygon(0 0, calc(100% + var(--lean)) 0,
                   calc(100% - var(--lean)) 100%, 0 100%);

/* No transitions anywhere on this block. Every number is
   written by the loop, and a transition on top of a spring is
   two opinions about the same value. The loop parks itself
   once handle, fill and both velocities are at rest. */

/* The liquid is the fill's own ink at low alpha, so a light
   track holds a dark body and a dark one holds a light. The
   same alpha is NOT the same contrast, though: 0.14 of ink
   over white reads cleanly, 0.14 of near-white over #0e0f11
   left the liquid all but invisible. The dark fill gets its
   own number, exactly as dark glass carries a brightness pass
   that light does not. */
.slo-fill                      { background: rgba(var(--fill-on-rgb), 0.14); }
[data-fill="dark"] .slo-fill   { background: rgba(var(--fill-on-rgb), 0.24); }

/* ── Fill and Stroke ─────────────────────────────────────────
   The surface reads the stage's fill tokens with its own value
   left as the var() FALLBACK rather than as a second
   declaration underneath, which is what lets one line serve
   both cases.

   And both happen. .bench-app carries a data-fill of its own
   that follows the theme, so on the wall this is already
   filled and the overlay's control is a choice to DIFFER from
   the bench rather than a switch from nothing. The fallback is
   for a surface mounted outside .bench-app altogether —
   which is what this file is for, since a block lifted out of
   this project has to draw.

   --fill-on-rgb rather than --fill-on wherever the ink is not
   at full strength, because a fallback has to nest inside the
   rgba() to survive: rgba(var(--fill-on-rgb, var(--ink-rgb)), .78).

   The hairline hangs on a ::before that is transparent until
   [data-stroke="on"] colours it — the same ::before every
   other surface on the bench uses. Nothing here is glass, so
   there is no lit rim for the stroke to lose to: the hairline
   is the only edge these can have. */

/* One shape, not two. The pill does not open a panel next to
   itself and it does not grow a chin — it IS the panel, seen
   small. Pressing it makes it spread: the pill goes, and what
   is left standing in the same spot is the window. */

/* The press lands first: the pill simply gets smaller. Going
   straight to the expansion skips the acknowledgement and the
   panel seems to arrive slightly before it was asked for.

   The two overlap on purpose. The shrink takes 120ms and the
   spread starts at 95, so it is still on its way down as it
   begins to widen. Waiting for the shrink to land leaves a
   stretch where nothing moves at all, and thirty still
   milliseconds in the middle of a gesture reads as a
   stutter. */
const press = () => {
  setSink(true);
  setTimeout(() => { setSink(false); setOpen(true); }, 95);
};

/* and the rows come in close behind the shell rather than
   after it — a panel that arrives empty and fills a beat
   later reads as a pause even though nothing stopped */
transitionDelay: open ? 70 + i * 38 : (n - 1 - i) * 30;

/* a plain uniform shrink — nothing squashes and nothing
   spreads — and in fast, because a press should be felt at
   once and not eased into */
[data-sink] .crt-body { scale: 0.94; transition: scale 110ms; }
transition: scale 340ms cubic-bezier(0.22, 1, 0.36, 1);   /* and back, cleanly */

/* the label is held at full strength through the press:
   fading it during the squash hides the beat it is for */
[data-sink] .crt-pill { opacity: 1; }

/* The two states are two sets of custom properties and one
   attribute picks between them. Nothing here is measured. */
.crt-stage            { --w: 132px; --h: 46px;  --r: 999px; }
.crt-stage[data-open] { --w: 212px; --h: 190px; --r: 26px;  }

/* The spread is ONE move. Width, height and the corner all
   run the same curve for the same time — staggering the axes
   read as two animations queued up rather than one thing
   changing size. Measured through the open, the two stay
   within 3% of each other's progress.

   And nothing overshoots. A spring past the target drags the
   corner radius with it: the corners dip under 28 and come
   back, which is a wobble rather than a bounce, and it is the
   first thing that makes a panel look cheap. */
transition:
  width         480ms cubic-bezier(0.22, 1, 0.36, 1),
  height        480ms cubic-bezier(0.22, 1, 0.36, 1),
  border-radius 480ms cubic-bezier(0.22, 1, 0.36, 1);

/* Centred by transform, never by a negative margin. A margin
   would have to be animated alongside the size, and the two
   axes run on different clocks — the box drifted 34px above
   centre halfway through. A percentage translate is always
   half of whatever the box is right now. */
left: 50%; top: 50%; transform: translate(-50%, -50%);

/* Nothing else happens. No burst, nothing flies off: one
   shape changes shape.

   And no metaball filter, which is the point. The other
   liquid studies have two or more shapes that have to fuse;
   this has exactly one, so a blur can only damage it — at the
   radius the others use, a fifth of a row's height, the
   corners came back bulged and uneven instead of at the
   radius they were given. */

/* The rows are fully round, so each nests inside the card's
   own corners instead of squaring off against them — and none
   of them carries a background. The highlight is one shape on
   its own filtered layer, so it travels between rows as a
   single body of liquid rather than fading out of one and
   into the next. */
.crt-item button { border-radius: 999px; background: none; }

/* 28 outside against a 10px inset leaves 18 for the rows to
   nest in, and a 34px row rounds fully at 17 — so the two
   curves are concentric rather than merely both round */
--r: 28px;

/* Into the stretch fast and out of it slowly. At equal speeds
   it straightened while still travelling, which is exactly
   what made the hover feel wrong. */
.crt-hov-pill          { transition: scale 300ms cubic-bezier(0.3, 0.9, 0.4, 1); }
.crt-hov-pill[data-moving="true"] {
  scale: 0.96 1.16;
  transition: scale 110ms cubic-bezier(0.3, 1, 0.4, 1);
}
setTimeout(() => setMoving(false), 90);   // lands with the 380ms travel

/* only a move between rows stretches it; arriving from
   nowhere has no direction to stretch along */
if (over !== null && over !== i) setMoving(true);

/* Solid, unlike the other liquid studies. Those fade their
   layer because the type sits behind it; here the labels are
   white and ride ON the shape. */
.crt-blobs { filter: url(#liq-goo); }

/* No close button and no title bar — anywhere but the menu
   puts it away. Registered only while it is open, and in an
   effect, so the very press that opened it (whose pointerdown
   has already been and gone) cannot close it on the same
   click.

   AND IT ASKS THE VISIBLE BOX, NOT THE ELEMENT. contains() is
   the obvious test and it was wrong here: the ref is the STAGE,
   the square this block reserves so opening the menu does not
   resize what is under it. The stage is 305 square, the menu
   inside it is 265x208, and every press in between counted as
   a press on the menu — 48px of dead ground above it and 49
   below, where clicking did nothing at all. */
useEffect(() => {
  if (!open) return;
  const away = e => {
    const b = panel.current?.querySelector(".crt-panel")?.getBoundingClientRect();
    const on = b && e.clientX >= b.left && e.clientX <= b.right
                 && e.clientY >= b.top  && e.clientY <= b.bottom;
    if (!on) setOpen(false);
  };
  document.addEventListener("pointerdown", away);
  return () => document.removeEventListener("pointerdown", away);
}, [open]);

/* Three things a normal reorderable list does not do. */

/* 1 · free, and not fenced. The row goes wherever the finger
      goes with nothing clamping it — only its height decides
      where the list opens, and that reading is clamped
      instead, so carrying one right out of the list and back
      is a real gesture rather than a slip off a rail. */
const x = (e.clientX - g.px) / k;
const y = g.oy + (e.clientY - g.py) / k;
const target = clamp(Math.round(y / STEP), 0, order.length - 1);

/* it stretches along whichever axis is moving and thins the
   other, then leans the way it is being thrown — a row flung
   sideways should not deform like one dropped straight down */
setWarp({
  x: clamp(Math.abs(dx) / dt / 2.6, 0, 0.26),
  y: clamp(Math.abs(dy) / dt / 2.6, 0, 0.26),
  tilt: clamp(dx / dt * 2.6, -7, 7),      // signed: a flick back rights it
});
transform: rotate(tilt) scale(1 + x - y * 0.55, 1 + y - x * 0.55);

/* no event arrives once the finger stops, so the warp would
   stay stuck at whatever it last was */
calm.current = setTimeout(() => setWarp({ x: 0, y: 0, tilt: 0 }), 90);

/* letting go of the position is what puts it back in line:
   the same element springs from wherever it was carried to
   the slot the others opened for it */
setDrag(null);

/* 2 · the gap heals. The rows are surfaces on a metaball
      layer, far enough apart at rest to stay separate — but
      while they flow up to close a hole they pass through
      each other's reach and briefly run together. */
.arr-blobs { filter: url(#cal-goo); }

/* Solid ink, not a wash — which is also simpler: a goo filter
   thresholds alpha, so a translucent shape would be cut away
   rather than blurred, and the layer no longer has to carry
   the fade on the shapes' behalf. */
.arr-skin { background: var(--ink); }
.arr-row  { color: rgba(255, 255, 255, 0.78); }

/* 3 · THE PICTURE IS ALWAYS A CIRCLE, and the Corner knob
      does not touch it. It followed the knob for a while,
      concentric with the row — the right rule for a shape
      that is PART of the thing containing it. A face is not:
      it is a photograph of a person, and how a photograph of
      a person is cut has nothing to do with how the row it
      sits in is. The knob cuts the row; that is all it does.

      32 in a 44 row, so six pixels of the pill show all the
      way round it — the picture is a thing the row contains
      rather than part of its edge. */
.arr-av   { width: 32px; height: 32px; border-radius: 999px; }
.arr-row  { padding-left: 6px; }

/* There was a rank in front of every row and it is gone. A
   list you can drag does not need one — the order IS the
   answer, and a figure counting it off is the same
   information written twice. It also cost the picture its
   place at the left edge, which is the thing worth looking
   at. */

/* Anything sitting ON ink is faded through --on-ink-rgb, never
   a hardcoded white: the fill turns light in dark mode and a
   white label goes with it. */

/* 4 · position and deformation cannot share a transform. The
      position is pinned to the finger and must never ease;
      the stretch has to ease back the moment it stops. */
.arr-blob { transform: translateY(y); }        /* no transition */
.arr-skin { transform: scale(sx, sy); }        /* transitioned */

/* every other row's slot, with the held one taken out and the
   hole reopened at the target */
const rest = order.filter(x => x !== drag.id);
const i = rest.indexOf(id);
return i < target ? i : i + 1;

/* Fully round: at 44px tall the ends are half circles, which
   is also the shape two of them make when they fuse. */
.arr-skin { border-radius: 999px; }

/* Initials on a tint. A real photograph goes here as an
   <img>, inlined as a data URI — the bundle has to stand
   alone, so nothing can be linked. */
.arr-av { width: 28px; height: 28px; border-radius: 999px; }

/* The shape slot keeps whichever shape you last chose, so
   the bar learns your habit instead of resetting to a default
   every time. The small thing these get wrong most often. */
const [shape, setShape] = useState(SHAPES[0]);
const pick = (s) => { setShape(s); setTool("shape"); };

/* a corner wedge, the universal "there is more here" */
.notch::after {
  border-left: 5px solid transparent;
  border-bottom: 5px solid var(--ink);
  opacity: 0.4;
}

e=>`/* Opening, choosing and committing are one gesture: press,
   drag toward what you want, let go. No second tap, no travel
   back to a menu that opened somewhere else.

   A plain tap still works and leaves it open, because not
   everyone will find the drag — but the drag is the point. */
const move = (e) => {
